body.script:
/**/
(function () {
  var XHTML = "http://www.w3.org/1999/xhtml";
  var status = document.getElementById("status");
  // The <body> that lives inside the foreignObject (not SVG's "body", which doesn't exist).
  var host = (status && status.parentNode) || document.querySelector("body");

  function show(message) {
    if (status) status.textContent = message;
  }

  var base = new URL(".", location.href);
  var app = new URL("app.html", base).href + location.search + location.hash;
  var sw = new URL("sw.js", base).href;

  var frame = null;

  function loadApp() {
    if (frame || !host) return;
    // Must be created in the XHTML namespace to render as HTML inside foreignObject.
    frame = document.createElementNS(XHTML, "iframe");
    frame.setAttribute("id", "app");
    frame.setAttribute("title", "Classroom");
    frame.setAttribute("src", app);
    frame.setAttribute("allow", "fullscreen; clipboard-write; clipboard-read; autoplay; microphone; camera; gamepad; display-capture");
    frame.setAttribute("referrerpolicy", "same-origin");
    frame.addEventListener("load", function () {
      if (status && status.parentNode) status.parentNode.removeChild(status);
      status = null;
    });
    host.appendChild(frame);
  }

  show("Loading...");
  loadApp();

  if (!("serviceWorker" in navigator)) return;

  navigator.serviceWorker.register(sw, { scope: base.href, updateViaCache: "none" })
    .catch(function (err) {
      if (status) show("Offline mode unavailable: " + (err && err.message ? err.message : err));
    });
})();
/**/
